  if (dateFrom) {                                             // line 157
    const from = new Date(dateFrom).getTime()
    result = result.filter((tx) => new Date(tx.createdAt).getTime() >= from)
  }

  if (dateTo) {                                               // line 162
    const to = new Date(dateTo).getTime() + 86400000
    result = result.filter((tx) => new Date(tx.createdAt).getTime() <= to)
  }

  return result
}, [transactions, filter, searchQuery, dateFrom, dateTo])
```

**Key observation:** The page fetches ALL transactions via `fetchTransactionsAction` (line 193) and then filters/searchs entirely in-memory. There is no server-side search query being used on this page.

### Data fetching (lines 189-205)
```ts
const fetchTransactions = useCallback(async () => {
  setLoading(true)
  setError(null)
  try {
    const res = await fetchTransactionsAction(user.id);   // line 193
    if (!res.ok) throw new Error(res.error ?? `HTTP ${res.status}`)
    const sorted = (res.data ?? []).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    )
    setTransactions(sorted)
  } catch (err) {
    setError(err instanceof Error ? err.message : "Failed to load transactions")
    setTransactions([])
  } finally {
    setLoading(false)
  }
}, [user.id])
