```ts
queryTransactionsHandler = async (
  request: FastifyRequest<{
    Params: { userId: Parameters<IWalletService["queryTransactions"]>[1] };
    Querystring: Parameters<IWalletService["queryTransactions"]>[0];
    Headers: ReturnType<typeof fromNodeHeaders>;
  }>,
  reply: FastifyReply,
) => {
  try {
    const session = await auth.api.getSession({
      headers: fromNodeHeaders(request.headers),
    });

    if (!session) {
      return sendError({
        reply,
        statusCode: 401,
        message: "UNAUTHORIZED",
        error: "ERROR FROM AUTH SERVICE",
      });
    }

    const transactions = await this.walletService.queryTransactions(
      request.query,          // passes the query params (status, from, to)
      request.params.userId,  // passes the userId param
    );

    sendSuccess<TWalletTransactionDTO[]>({
      reply,
      statusCode: 200,
      message: "Successfully queried transactions",
      data: toTransactionsDTO(transactions),
    });
  } catch (error: unknown) {
    sendError({
      reply,
      statusCode: 500,
      message: "FAILED_TO_QUERY_TRANSACTIONS",
      error: error instanceof Error ? error.message : "INTERNAL_SERVER_ERROR",
    });
  }
};
```

### Service implementation
**File:** `/home/coderx85/Projects/Work/.GITHUB/wave/server/src/modules/wallet/service/wallet-service.ts`  
**Lines 209-242:**
```ts
queryTransactions(
  query: TTransactionQuery,
  userId: TUserId,
): Promise<ITransaction[]> {
  return tryCatch({
    ctx: async () => {
      switch (query.status) {
        case "success": {
          const successfulTransactions =
            await this.transactionRepo.successfulTransactions({
              userId,
              dateRange: query.dateRange,
            });
          return successfulTransactions;
        }

        case "failed": {
          const failedTransactions =
            await this.transactionRepo.failedTransactions({
              userId,
              dateRange: query.dateRange,
            });
          return failedTransactions;
        }

        default:
          throw new Error(
            "Invalid status value. Allowed values are 'success' or 'failed'.",
          );
      }
    },
    errorMessage: "FAILED_TO_QUERY_TRANSACTIONS",
  });
}
```

### What it searches by
- **`status`** (required) — only `"success"` or `"failed"`; `"pending"` is NOT supported by the query endpoint
- **`from`** / **`to`** (both optional) — mapped to a `dateRange` object in the service layer
- **No text/full-text search** — no search by name, account number, or any string field

